async function api(path, options = {}) {
  const headers = { ...(options.body && !(options.body instanceof FormData) ? {'Content-Type':'application/json'} : {}), ...(options.headers || {}) };
  const r = await fetch(API + path, { credentials:'include', ...options, headers });
  let d = null; try { d = await r.json(); } catch (_) {}
  if (!r.ok) throw Error(d?.message || 'Request failed');
  return d;
}
async function formPost(path, values) {
  const body = Object.entries(values).map(([k,v]) => encodeURIComponent(k)+'='+encodeURIComponent(v ?? '')).join('&');
  const r = await fetch(API + path, { method:'POST', credentials:'include', headers:{'Content-Type':'application/x-www-form-urlencoded'}, body });
  let d = null; try { d = await r.json(); } catch (_) {}
  if (!r.ok) throw Error(d?.message || 'Request failed');
  return d;
}
function img(v) { if (!v) return IMAGE_BASE+'/default-avatar.png'; const x=String(v); if(x.startsWith('http')) return x; if(x.startsWith('/images/')) return IMAGE_BASE+x.replace('/images',''); return API+(x.startsWith('/')?x:'/images/'+x); }
