function Login({done}) {
  const [u,setU]=useState(''),[p,setP]=useState(''),[show,setShow]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[forgot,setForgot]=useState(false);
  const submit=async()=>{if(!u||!p){setError('Invalid username or password.');return}setBusy(true);setError('');try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:u,password:p})});if(!d?.success)throw Error(d?.message||'Invalid username or password.');await AsyncStorage.setItem('emsUser',JSON.stringify(d));done(d)}catch(e){setError(e.message||'Invalid username or password.')}finally{setBusy(false)}};
  return <SafeAreaView style={s.loginSafe}><StatusBar barStyle="dark-content" backgroundColor="#fff"/><ScrollView contentContainerStyle={s.loginWrap} keyboardShouldPersistTaps="handled"><View style={s.loginCard}><View style={s.loginLeft}><Image source={{uri:IMAGE_BASE+'/img1.png'}} style={s.loginImage} resizeMode="contain"/><Text style={s.heroTitle}>Grow Your <Text style={{color:C.green}}>Workspace</Text> Experience</Text><Text style={s.heroText}>It is certainly important because it is only through hard work that we can achieve the goals of our life. Thus, we all must work hard.</Text></View><View style={s.loginRight}><Text style={s.loginTitle}>Login</Text><View style={s.loginInput}><Icon name="email-outline" size={20} color={C.green}/><TextInput style={s.loginText} value={u} onChangeText={setU} placeholder="Enter User name or Email" placeholderTextColor="#999" autoCapitalize="none" autoCorrect={false}/></View><View style={s.loginInput}><Icon name="lock-outline" size={20} color={C.green}/><TextInput style={s.loginText} value={p} onChangeText={setP} placeholder="Enter Your Password" placeholderTextColor="#999" secureTextEntry={!show}/><TouchableOpacity onPress={()=>setShow(!show)}><Icon name={show?'eye-outline':'eye-off-outline'} size={20} color={C.muted}/></TouchableOpacity></View><TouchableOpacity style={s.forgot} onPress={()=>setForgot(true)}><Text style={s.forgotText}>Forgot Password?</Text></TouchableOpacity><Button onPress={submit} disabled={busy}>{busy?'Login...':'Login'}</Button>{error?<View style={s.alert}><Text style={s.alertText}>{error}</Text></View>:null}</View></View></ScrollView><ForgotPassword visible={forgot} onClose={()=>setForgot(false)}/></SafeAreaView>;
}
function ForgotPassword({visible,onClose}) { const [step,setStep]=useState(1),[email,setEmail]=useState(''),[otp,setOtp]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[msg,setMsg]=useState(''); const send=async()=>{if(!email)return Alert.alert('Forgot Password','Enter your email address.');setBusy(true);try{await formPost('/forgot-password',{email});setStep(2);setMsg('OTP sent to your email.')}catch(e){Alert.alert('Forgot Password',e.message)}finally{setBusy(false)}};const verify=async()=>{setBusy(true);try{await formPost('/verify-otp',{email,otp});setStep(3);setMsg('OTP verified.')}catch(e){Alert.alert('Forgot Password',e.message)}finally{setBusy(false)}};const reset=async()=>{if(!password)return Alert.alert('Reset Password','Enter a new password.');setBusy(true);try{await formPost('/reset-password',{email,password});Alert.alert('Password Reset','Password changed successfully.');onClose();setStep(1);setEmail('');setOtp('');setPassword('')}catch(e){Alert.alert('Reset Password',e.message)}finally{setBusy(false)}};return <ModalBox visible={visible} onClose={onClose} title={step===1?'Forgot Password?':step===2?'Verify OTP':'Reset Password'}>{step===1&&<><Text style={s.modalDescription}>Enter your registered email to receive an OTP.</Text><Field label="Email" value={email} onChangeText={setEmail} placeholder="Enter your email"/><Button onPress={send} disabled={busy}>{busy?'Sending...':'Send OTP'}</Button></>}{step===2&&<><Text style={s.modalDescription}>{msg}</Text><Field label="OTP" value={otp} onChangeText={setOtp} placeholder="Enter OTP"/><Button onPress={verify} disabled={busy}>{busy?'Verifying...':'Verify OTP'}</Button></>}{step===3&&<><Text style={s.modalDescription}>{msg}</Text><Field label="New Password" value={password} onChangeText={setPassword} placeholder="Enter new password" secureTextEntry/><Button onPress={reset} disabled={busy}>{busy?'Saving...':'Reset Password'}</Button></>}</ModalBox>; }

