function PendingOnboarding() { const [e,setE]=useState([]),[selected,setSelected]=useState(null);const load=()=>api('/api/admin/onboarding/pending').then(x=>setE(x||[])).catch(()=>{});useEffect(load,[]);const finish=async(path,id)=>{try{const d=await api(`/api/admin/onboarding/${path}/${id}`,{method:'POST'});Alert.alert('Onboarding',d.message||'Updated successfully');setSelected(null);load()}catch(err){Alert.alert('Onboarding',err.message)}};return <Page title="Pending Onboarding Reviews" refresh={load}><Card style={{padding:0,overflow:'hidden'}}><ScrollView horizontal><View style={{minWidth:760}}><View style={s.tableHead}>{['Employee','Email','Username','Status','Action'].map((h,i)=><Text key={h} style={[s.th,{width:[230,170,140,150,160][i]}]}>{h}</Text>)}</View>{e.length?e.map(x=><View style={s.tableRow} key={x.id}><Text style={[s.td,{width:230}]}>{x.firstname} {x.lastname}{'\n'}ID: {x.id}</Text><Text style={[s.td,{width:170}]}>{x.email}</Text><Text style={[s.td,{width:140}]}>{x.username}</Text><Text style={[s.td,{width:150}]}>{x.overallStatus==='DETAILS_SUBMITTED'?'Ready for Review':'Changes Pending'}</Text><View style={[s.actionCell,{width:160}]}><Button small onPress={()=>setSelected(x)}>Review Details</Button></View></View>):<Empty text="No pending onboarding applications at this time."/>}</View></ScrollView></Card><ReviewOnboarding employee={selected} onClose={()=>setSelected(null)} onRefresh={load} onDecision={finish}/></Page>; }
function ReviewOnboarding({employee,onClose,onRefresh,onDecision}) { const [decisions,setDecisions]=useState({}),[reasons,setReasons]=useState({}),[busy,setBusy]=useState(false);useEffect(()=>{if(employee){const d={};REVIEW_FIELDS.forEach(([k])=>{d[k+'Status']=employee.employeeDetails?.[k+'Status']||'APPROVED'});setDecisions(d);setReasons({})}},[employee]);if(!employee)return null;const set=(key,v)=>setDecisions({...decisions,[key+'Status']:v});const submit=async()=>{setBusy(true);try{const body={...decisions};Object.keys(reasons).forEach(k=>{body[k+'RejectionReason']=reasons[k]});const d=await api(`/api/admin/onboarding/review/${employee.id}`,{method:'POST',body:JSON.stringify(body)});Alert.alert('Review',d.message||'Review saved');onClose();onRefresh()}catch(e){Alert.alert('Review',e.message)}finally{setBusy(false)}};return <ModalBox visible={!!employee} onClose={onClose} title={`Review Onboarding - ${employee.firstname} ${employee.lastname}`}><ScrollView style={{maxHeight:560}}>{REVIEW_FIELDS.map(([key,label])=>{const status=decisions[key+'Status']||'APPROVED';return <View key={key} style={s.reviewRow}><View style={{flex:1}}><Text style={s.reviewLabel}>{label}</Text><Text style={s.reviewValue}>{getReviewValue(employee,key)}</Text>{status==='REJECTED'&&<TextInput value={reasons[key]||''} onChangeText={v=>setReasons({...reasons,[key]:v})} placeholder="Rejection reason" placeholderTextColor="#999" style={[s.input,s.reason]}/>}</View><View style={s.reviewActions}><TouchableOpacity onPress={()=>set(key,'APPROVED')} style={[s.reviewIcon,status==='APPROVED'&&s.reviewApproved]}><Icon name="check" size={20} color="#198754"/></TouchableOpacity><TouchableOpacity onPress={()=>set(key,'REJECTED')} style={[s.reviewIcon,status==='REJECTED'&&s.reviewRejected]}><Icon name="close" size={20} color={C.danger}/></TouchableOpacity></View></View>})}</ScrollView><View style={s.actionRow}><Button onPress={submit} disabled={busy}>{busy?'Saving...':'Save Review'}</Button><Button outline onPress={()=>onDecision('approve',employee.id)}>Approve All</Button><Button outline danger onPress={()=>onDecision('reject',employee.id)}>Request Changes</Button></View></ModalBox>; }
function getReviewValue(e,key){const d=e.employeeDetails||{};const map={phone:d.personalPhone,address:d.personalAddress,city:d.personalCity,gender:d.personalGender,dob:d.personalDateOfBirth,emergency:d.personalEmergencyNumber,maritalField:d.personalMaritalStatus,language:d.personalLanguage,blood:d.personalBloodGroup,aadhar:d.aadharNumber,pan:d.panNumber,account:d.accountNumber,bankName:d.bankName,ifsc:d.ifscCode,branch:d.personalBranch,degreeName:d.degreeName,degreeInst:d.degreeInstitution,photo:d.photoData?'Available':'Not uploaded',mark10th:d.mark10thData?'Available':'Not uploaded',mark12th:d.mark12thData?'Available':'Not uploaded',sem1:d.sem1Data?'Available':'Not uploaded',sem2:d.sem2Data?'Available':'Not uploaded',sem3:d.sem3Data?'Available':'Not uploaded',sem4:d.sem4Data?'Available':'Not uploaded',sem5:d.sem5Data?'Available':'Not uploaded',sem6:d.sem6Data?'Available':'Not uploaded',sem7:d.sem7Data?'Available':'Not uploaded',sem8:d.sem8Data?'Available':'Not uploaded',transferCert:d.transferCertData?'Available':'Not uploaded',provisionalCert:d.provisionalCertData?'Available':'Not uploaded',courseCompletion:d.courseCompletionData?'Available':'Not uploaded'};return val(map[key]);}

