function EmployeeHourly({e}) { const id=e?.employeeId||e?.id,[rows,setRows]=useState([{timeSlot:'',taskDescription:'',status:'In Progress'}]),[reports,setReports]=useState([]);const load=()=>api(`/api/hourly-reports/employee/${id}`).then(setReports).catch(()=>{});useEffect(load,[id]);const setRow=(i,k,v)=>setRows(rows.map((r,j)=>j===i?{...r,[k]:v}:r));const submit=async()=>{const valid=rows.filter(r=>r.timeSlot.trim()&&r.taskDescription.trim());if(!valid.length)return Alert.alert('Hourly Work Report','Please enter at least one time slot and task description before submitting.');try{await api('/api/hourly-reports/submit',{method:'POST',body:JSON.stringify({employeeId:id,reports:valid})});Alert.alert('Success','Hourly report submitted successfully!');setRows([{timeSlot:'',taskDescription:'',status:'In Progress'}]);load()}catch(x){Alert.alert('Hourly Work Report',x.message)}};return <Page title="Hourly Work Report"><Card><View style={s.topLine}><Text style={s.section}>Submit Work Entries</Text><Button small outline onPress={()=>setRows([...rows,{timeSlot:'',taskDescription:'',status:'In Progress'}])}>+ Add Entry</Button></View>{rows.map((r,i)=><View style={s.entry} key={i}><Field label="Time Slot" value={r.timeSlot} onChangeText={v=>setRow(i,'timeSlot',v)} placeholder="e.g. 10:00 AM - 11:00 AM"/><Field label="Task Description" value={r.taskDescription} onChangeText={v=>setRow(i,'taskDescription',v)} placeholder="Enter task details..." multiline/><Select label="Status" value={r.status} options={['In Progress','Completed','Pending Review','In Meeting']} onChange={v=>setRow(i,'status',v)}/>{rows.length>1&&<Button small danger onPress={()=>setRows(rows.filter((_,j)=>j!==i))}>Remove</Button>}</View>)}<Button onPress={submit}>Submit All Reports</Button></Card><Card><Text style={s.section}>Submitted Reports</Text>{reports.length?reports.map(r=><View key={r.id} style={s.report}><Text style={s.bold}>{val(r.timeSlot)}</Text><Text style={s.muted}>{val(r.taskDescription)}</Text><Badge>{val(r.status)}</Badge></View>):<Empty text="No reports found"/>}</Card></Page>; }

function App() { const [u,setU]=useState(null),[loading,setLoading]=useState(true),[page,setPage]=useState('Overview');useEffect(()=>{AsyncStorage.getItem('emsUser').then(async raw=>{if(raw){try{const me=await api('/api/auth/me');setU(me?.success?me:JSON.parse(raw))}catch(_){try{setU(JSON.parse(raw))}catch(__){}}}}).finally(()=>setLoading(false))},[]);const logout=async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch(_){try{await api('/logout',{method:'GET'})}catch(__){}}await AsyncStorage.removeItem('emsUser');setU(null);setPage('Overview')};if(loading)return <SafeAreaView style={s.loading}><ActivityIndicator size="large" color={C.green}/></SafeAreaView>;if(!u)return <Login done={x=>{setU(x);setPage('Overview')}}/>;const admin=String(u.role||u.userType||'').toUpperCase().includes('ADMIN');let body;if(admin){body=page==='Overview'?<AdminDashboard pending={()=>setPage('Pending Onboarding')}/>:page==='Add Employee'?<AddEmployee/>:page==='Employee List'?<EmployeeList/>:page==='Pending Onboarding'?<PendingOnboarding/>:page==='Attendance'?<AdminAttendance/>:page==='Leave'?<AdminLeave/>:page==='Hourly Reports'?<AdminHourly/>:page==='Notifications'?<Notifications admin/>:<Settings/>}else{body=page==='Overview'?<EmployeeDashboard e={u}/>:page==='Profile'?<EmployeeProfile e={u}/>:page==='Attendance'?<EmployeeAttendance e={u}/>:page==='Leave'?<EmployeeLeave e={u}/>:page==='Hourly Report'?<EmployeeHourly e={u}/>:<Notifications employee={u}/>}return <Shell admin={admin} page={page} setPage={setPage} logout={logout} employee={admin?null:u}>{body}</Shell>; }

